# Unicode ranges for script detection
def _detect_script(text):
    counts = {"latin": 0, "cyrillic": 0, "arabic": 0, "cjk": 0, "japanese": 0, "korean": 0, "devanagari": 0}
    for ch in text:
        cp = ord(ch)
        if 0x0041 <= cp <= 0x024F:
            counts["latin"] += 1
        elif 0x0400 <= cp <= 0x04FF:
            counts["cyrillic"] += 1
        elif 0x0600 <= cp <= 0x06FF:
            counts["arabic"] += 1
        elif 0x4E00 <= cp <= 0x9FFF:
            counts["cjk"] += 1
        elif (0x3040 <= cp <= 0x309F) or (0x30A0 <= cp <= 0x30FF):
            counts["japanese"] += 1
        elif 0xAC00 <= cp <= 0xD7AF:
            counts["korean"] += 1
        elif 0x0900 <= cp <= 0x097F:
            counts["devanagari"] += 1
    return max(counts, key=counts.get), counts


def handler(event):
    text = event.get("text") if isinstance(event, dict) else None
    if not text or not isinstance(text, str):
        return {"ok": False, "error": "text (string) is required"}
    try:
        t = text.lower()
        words = set(re.findall(r'\b\w+\b', t))

        # Script detection first
        dominant_script, script_counts = _detect_script(text)
        if dominant_script == "cyrillic" and script_counts["cyrillic"] > 5:
            return {"ok": True, "result": {"language": "Russian", "language_code": "ru"}, "language": "Russian", "language_code": "ru", "confidence": 0.9, "scores": {"ru": 0.9}}
        if dominant_script == "arabic" and script_counts["arabic"] > 5:
            return {"ok": True, "result": {"language": "Arabic", "language_code": "ar"}, "language": "Arabic", "language_code": "ar", "confidence": 0.9, "scores": {"ar": 0.9}}
        if dominant_script == "cjk" and script_counts["cjk"] > 5:
            return {"ok": True, "result": {"language": "Chinese", "language_code": "zh"}, "language": "Chinese", "language_code": "zh", "confidence": 0.9, "scores": {"zh": 0.9}}
        if dominant_script == "japanese" and script_counts["japanese"] > 5:
            return {"ok": True, "result": {"language": "Japanese", "language_code": "ja"}, "language": "Japanese", "language_code": "ja", "confidence": 0.9, "scores": {"ja": 0.9}}
        if dominant_script == "korean" and script_counts["korean"] > 5:
            return {"ok": True, "result": {"language": "Korean", "language_code": "ko"}, "language": "Korean", "language_code": "ko", "confidence": 0.9, "scores": {"ko": 0.9}}
        if dominant_script == "devanagari" and script_counts["devanagari"] > 5:
            return {"ok": True, "result": {"language": "Hindi", "language_code": "hi"}, "language": "Hindi", "language_code": "hi", "confidence": 0.9, "scores": {"hi": 0.9}}

        # Word overlap scoring for Latin-script languages
        scores = {}
        for (lang_name, lang_code), vocab in LANGUAGE_PROFILES.items():
            overlap = len(words & vocab)
            scores[lang_code] = {"name": lang_name, "score": overlap}

        best_code = max(scores, key=lambda k: scores[k]["score"])
        best_score = scores[best_code]["score"]
        total = sum(v["score"] for v in scores.values()) or 1
        confidence = round(best_score / total, 4) if best_score > 0 else 0.0

        if best_score == 0:
            best_code = "en"
            scores[best_code]["name"] = "English"
            confidence = 0.3

        return {
            "ok": True,
            "result": {"language": scores[best_code]["name"], "language_code": best_code},
            "language": scores[best_code]["name"],
            "language_code": best_code,
            "confidence": confidence,
            "scores": {k: v["score"] for k, v in scores.items()}
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}
